        sides_.za * sides_.za); /*L2 Norm*/
}

HyperBox6D::HyperBox6D() {
    value_ = -1;
    center_ = Point6D(0, 0, 0, 0, 0, 0);
    sides_ = Point6D(0, 0, 0, 0, 0, 0);
