function [VAL, Fmin, Xmin] = Arewedone(OPTI, VAL, MSS, RECT)
%--------------------------------------------------------------------------
[Fmin, fminindex] =  min(MSS.FF(1:VAL.I));
Xmin              = RECT(fminindex).pmin;

